CREATE TABLE community_post(id uuid PRIMARY KEY,club_id uuid REFERENCES club(id),user_id uuid NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REMOVED','DELETED')),kind varchar(20) NOT NULL DEFAULT 'POST' CHECK(kind IN ('POST','NOTICE')),body text NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE community_comment(id uuid PRIMARY KEY,post_id uuid NOT NULL REFERENCES community_post(id),user_id uuid NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REMOVED','DELETED')),body text NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE community_post_photo(post_id uuid NOT NULL REFERENCES community_post(id),file_id uuid NOT NULL,position integer NOT NULL CHECK(position>=0),PRIMARY KEY(post_id,file_id),UNIQUE(post_id,position));
CREATE TABLE community_like(post_id uuid NOT NULL REFERENCES community_post(id),user_id uuid NOT NULL REFERENCES app_user(id),PRIMARY KEY(post_id,user_id));
CREATE TABLE community_content_revision(id uuid PRIMARY KEY,content_id uuid NOT NULL,content_type varchar(20) NOT NULL,version bigint NOT NULL,body text NOT NULL,action varchar(20) NOT NULL,actor_id uuid NOT NULL REFERENCES app_user(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE community_follow(user_id uuid NOT NULL REFERENCES app_user(id),target_id uuid NOT NULL REFERENCES app_user(id),PRIMARY KEY(user_id,target_id),CHECK(user_id<>target_id));
CREATE TABLE community_block(user_id uuid NOT NULL REFERENCES app_user(id),target_id uuid NOT NULL REFERENCES app_user(id),PRIMARY KEY(user_id,target_id),CHECK(user_id<>target_id));
CREATE TABLE community_room(id uuid PRIMARY KEY,kind varchar(20) NOT NULL CHECK(kind IN ('DIRECT','GROUP_DM','CLUB','EVENT')),title varchar(100),club_id uuid REFERENCES club(id),event_id uuid REFERENCES club_event(id),user_a uuid REFERENCES app_user(id),user_b uuid REFERENCES app_user(id),requester_id uuid REFERENCES app_user(id),status varchar(20) NOT NULL CHECK(status IN ('PENDING','ACTIVE','DECLINED')),created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='DIRECT' AND user_a IS NOT NULL AND user_b IS NOT NULL AND user_a<user_b AND club_id IS NULL AND event_id IS NULL AND requester_id IN (user_a,user_b)) OR (kind='GROUP_DM' AND title IS NOT NULL AND club_id IS NULL AND event_id IS NULL AND user_a IS NULL AND user_b IS NULL) OR (kind='CLUB' AND club_id IS NOT NULL AND event_id IS NULL AND user_a IS NULL AND user_b IS NULL) OR (kind='EVENT' AND event_id IS NOT NULL AND club_id IS NOT NULL AND user_a IS NULL AND user_b IS NULL)));
CREATE UNIQUE INDEX community_direct_unique ON community_room(user_a,user_b) WHERE kind='DIRECT';
CREATE UNIQUE INDEX community_club_room_unique ON community_room(club_id) WHERE kind='CLUB';
CREATE UNIQUE INDEX community_event_room_unique ON community_room(event_id) WHERE kind='EVENT';
CREATE TABLE community_room_member(room_id uuid NOT NULL REFERENCES community_room(id),user_id uuid NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL CHECK(status IN ('INVITED','ACTIVE','DECLINED','LEFT')),inviter_id uuid NOT NULL REFERENCES app_user(id),min_sequence bigint NOT NULL DEFAULT 0 CHECK(min_sequence>=0),joined_at timestamptz,left_at timestamptz,PRIMARY KEY(room_id,user_id));
CREATE TABLE community_message(id uuid PRIMARY KEY,sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,room_id uuid NOT NULL REFERENCES community_room(id),user_id uuid NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REMOVED','DELETED')),version bigint NOT NULL DEFAULT 0,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX community_message_cursor ON community_message(room_id,sequence);
CREATE INDEX community_post_recent ON community_post(created_at DESC,id);
CREATE INDEX community_comment_post ON community_comment(post_id,created_at,id);

